#include "stm_helper/my_stm_helper.h"
#include "helper/helper.h"

#include <stdint.h>
#include <math.h>

// Computed orientation angles from the MPU6050 (degrees).
// Updated every 20 ms by the TIM3 interrupt.
Angles angles = {0.0f, 0.0f, 0.0f};

// Per-axis servo behaviour.
enum AXIS_STATE {
    FREE,       // near level: hold the servo at its rest pulse
    COMPLIANT,  // mid range: servo follows the measured angle
    CLAMPED     // past the stop: servo held at its limit
};

// MANUAL runs the axis FSMs; AUTO latches once roll and pitch are both clamped.
enum MODE {
    AUTO,
    MANUAL
};

enum MODE curMode = MANUAL;
enum AXIS_STATE pitch = FREE, tilt = FREE, roll = FREE;  // every axis starts at rest

void fsm_pitch(void) {
    float mag = fabsf(angles.pitch);  // thresholds use magnitude; sign picks which stop
    switch (pitch) {
        case FREE:
            if (mag >= 30.0f) {  // leave rest once |pitch| reaches 30 deg
                pitch = COMPLIANT;
                set_pitch(servo_deg_to_us(90.0f + angles.pitch));  // 90 deg is servo centre
            } else {
                set_pitch(1500);  // hold the 90 deg pulse
            }
            break;
        case COMPLIANT:
            if (mag < 25.0f) {  // 5 deg hysteresis before returning to FREE
                pitch = FREE;
                set_pitch(1500);
            } else if (mag > 50.0f) {  // hard stop once |pitch| passes 50 deg
                pitch = CLAMPED;
                set_pitch(angles.pitch >= 0.0f ? servo_deg_to_us(140.0f) : servo_deg_to_us(40.0f));
            } else {
                set_pitch(servo_deg_to_us(90.0f + angles.pitch));  // track pitch around centre
            }
            break;
        case CLAMPED:
            if (mag <= 45.0f) {  // release 5 deg before the clamp threshold
                pitch = COMPLIANT;
                set_pitch(servo_deg_to_us(90.0f + angles.pitch));
            } else {
                // Positive pitch stops at 140 deg, negative at 40 deg.
                set_pitch(angles.pitch >= 0.0f ? servo_deg_to_us(140.0f) : servo_deg_to_us(40.0f));
            }
            break;
    }
}

void fsm_roll(void) {
    float mag = fabsf(angles.roll);  // same 30/25/50/45 hysteresis as pitch
    switch (roll) {
        case FREE:
            if (mag >= 30.0f) {  // leave rest once |roll| reaches 30 deg
                roll = COMPLIANT;
                set_roll(servo_deg_to_us(90.0f + angles.roll));  // 90 deg is servo centre
            } else {
                set_roll(1500);  // hold the 90 deg pulse
            }
            break;
        case COMPLIANT:
            if (mag < 25.0f) {  // 5 deg hysteresis before returning to FREE
                roll = FREE;
                set_roll(1500);
            } else if (mag > 50.0f) {  // hard stop once |roll| passes 50 deg
                roll = CLAMPED;
                set_roll(angles.roll >= 0.0f ? servo_deg_to_us(140.0f) : servo_deg_to_us(40.0f));
            } else {
                set_roll(servo_deg_to_us(90.0f + angles.roll));  // track roll around centre
            }
            break;
        case CLAMPED:
            if (mag <= 45.0f) {  // release 5 deg before the clamp threshold
                roll = COMPLIANT;
                set_roll(servo_deg_to_us(90.0f + angles.roll));
            } else {
                // Positive roll stops at 140 deg, negative at 40 deg.
                set_roll(angles.roll >= 0.0f ? servo_deg_to_us(140.0f) : servo_deg_to_us(40.0f));
            }
            break;
    }
}

void fsm_tilt(void) {
    // Tilt is a magnitude, so this axis only moves one way from 0 deg.
    switch (tilt) {
        case FREE:
            if (angles.tilt > 20.0f) {  // leave rest once combined tilt passes 20 deg
                tilt = COMPLIANT;
                set_tilt(servo_deg_to_us(2.0f * angles.tilt));  // servo moves twice the tilt
            } else {
                set_tilt(500);  // 0 deg rest pulse
            }
            break;
        case COMPLIANT:
            if (angles.tilt < 15.0f) {  // 5 deg hysteresis before returning to FREE
                tilt = FREE;
                set_tilt(500);
            } else if (angles.tilt >= 70.0f) {  // hard stop at 140 deg once tilt hits 70
                tilt = CLAMPED;
                set_tilt(servo_deg_to_us(140.0f));
            } else {
                set_tilt(servo_deg_to_us(2.0f * angles.tilt));
            }
            break;
        case CLAMPED:
            if (angles.tilt <= 65.0f) {  // release 5 deg before the clamp threshold
                tilt = COMPLIANT;
                set_tilt(servo_deg_to_us(2.0f * angles.tilt));
            } else {
                set_tilt(servo_deg_to_us(140.0f));  // stay on the stop
            }
            break;
    }
}

void fsm_mode(void) {
    static bool prev_btn = false;                 // last sample, so we only see the press edge
    bool now = GPIO_InputReadPin(GPIOA, 12);      // PA12 mode button, active high
    bool rising = (!prev_btn && now);             // true for one tick when the button is pressed
    prev_btn = now;

    switch (curMode) {
        case MANUAL:
            // Enter AUTO if both roll and pitch are clamped, or the button is pressed.
            if ((roll == CLAMPED && pitch == CLAMPED) || rising) {
                curMode = AUTO;
                set_auto_led(true);
                set_manual_led(false);
            } else {
                set_manual_led(true);
                set_auto_led(false);
            }
            break;
        case AUTO:
            // Button returns to MANUAL only when roll and pitch are both free.
            if (rising && (roll == FREE && pitch == FREE)) {
                curMode = MANUAL;
                set_manual_led(true);
                set_auto_led(false);
            } else {
                set_auto_led(true);
                set_manual_led(false);
            }
            break;
    }
}

// TIM3 update interrupt: acknowledge the event so execution can resume.
// Reads fresh MPU6050 data at the start of every 20 ms tick.
void TIM3_IRQHandler(void) {
    if ((TIM3->SR & TIM_SR_UIF) != 0U) {
        // Read accelerometer and compute roll/pitch/tilt into the global struct.
        readAngles(&angles);

        // Update FSM states
        fsm_pitch();
        fsm_roll();
        fsm_tilt();
        fsm_mode();

        // Timer status flags clear on writing 0; leave other flags unchanged.
        TIM3->SR = ~TIM_SR_UIF;
    }
}

void init() {
    // 1. Clocks Enable
    Clock_Enable(GPIOA_BUS);
    Clock_Enable(GPIOB_BUS);
    Clock_Enable(TIM3_BUS);
    Clock_Enable(TIM16_BUS); 
    Clock_Enable(I2C1_BUS);

    // 2. Button: PA12 input, pull-down (polled each TIM3 tick in fsm_mode)
    GPIO_InitPin(GPIOA, 12, INPUT, PULL_DOWN);

    // 3. LEDs: PA2 = Autopilot, PB11 = Manual. Start in MANUAL.
    GPIO_InitPin(GPIOA, 2, OUTPUT, NONE);
    GPIO_InitPin(GPIOB, 11, OUTPUT, NONE);
    set_auto_led(false);             // autopilot LED off
    set_manual_led(true);            // manual LED on

    // 4. Servo pins -> TIM3 (AF1): PB4 = CH1 roll, PB5 = CH2 pitch, PB0 = CH3 tilt
    GPIO_InitPin(GPIOB, 4, ALT, NONE);  GPIO_ConnectPeripheral(GPIOB, 4, 1);
    GPIO_InitPin(GPIOB, 5, ALT, NONE);  GPIO_ConnectPeripheral(GPIOB, 5, 1);
    GPIO_InitPin(GPIOB, 0, ALT, NONE);  GPIO_ConnectPeripheral(GPIOB, 0, 1);

    // 5. I2C pins: PB8 = SCL, PB9 = SDA (AF6)
    GPIO_InitPin(GPIOB, 8, ALT, PULL_UP);  GPIO_ConnectPeripheral(GPIOB, 8, 6);
    GPIO_InitPin(GPIOB, 9, ALT, PULL_UP);  GPIO_ConnectPeripheral(GPIOB, 9, 6);
    GPIOB->OTYPER |= (1 << 8) | (1 << 9);  // I2C pins must be open-drain

    // 6. TIM16: free-running 1 ms counter used by check_timeout()
    //    Must be running BEFORE any I2C call.
    Timer_Init(TIM16, TIM16_IRQn, 47999, 0xFFFF, false, false, true, true);

    // 7. I2C1 at 100 kHz, then wake the MPU6050
    I2C_Master_Init(I2C1, 11, 19, 19);
    MPU6050_Init();   // returns false if the sensor doesn't answer

    // 8. Servo PWM channels on TIM3 (counter not started yet)
    PWM_Init(TIM3, TIM_CHANNEL_1, TIM_MODE_OUTPUT_PWM1, false);
    PWM_Init(TIM3, TIM_CHANNEL_2, TIM_MODE_OUTPUT_PWM1, false);
    PWM_Init(TIM3, TIM_CHANNEL_3, TIM_MODE_OUTPUT_PWM1, false);

    // 9. Starting servo positions (the FREE state of each FSM)
    set_roll(1500);    // roll  = 90 deg
    set_pitch(1500);   // pitch = 90 deg
    set_tilt(500);     // tilt  = 0 deg

    // 10. TIM3 last: 50 Hz PWM, and its update interrupt is the 20 ms loop tick
    Timer_Init(TIM3, TIM3_IRQn, 47, 19999, true, true, true, true);
}

int main(void)
{
    init();  // returns immediately; TIM3 IRQ runs the control loop every 20 ms
}
